-- ---------------------------------------------------------------------------
-- 2. team_members.event_id: add (nullable) and backfill from teams. The
--    previous app version does not set it and keeps inserting NULL, which the
--    unique and foreign key constraints below tolerate.
-- ---------------------------------------------------------------------------
ALTER TABLE "bingoscape-next_team_members" ADD COLUMN IF NOT EXISTS "event_id" uuid;--> statement-breakpoint
UPDATE "bingoscape-next_team_members" tm
SET "event_id" = t."event_id"
FROM "bingoscape-next_teams" t
WHERE tm."team_id" = t."id" AND tm."event_id" IS DISTINCT FROM t."event_id";--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 3. event_participants: one row per (event, user). Keep the highest role,
--    then the oldest row. Buy-ins and donations are re-pointed to the keeper
--    (they would otherwise cascade-delete with the duplicate) and the removed
--    rows are copied to the quarantine table first.
-- ---------------------------------------------------------------------------
INSERT INTO "bingoscape-next_event_participants_quarantine"
  ("reason", "original_id", "event_id", "user_id", "role", "original_created_at", "original_updated_at", "kept_participant_id")
SELECT 'duplicate_event_user', r."id", r."event_id", r."user_id", r."role"::text, r."created_at", r."updated_at", r."keeper_id"
FROM (
  SELECT ep.*,
         first_value(ep."id") OVER w AS "keeper_id",
         row_number() OVER w AS "rn"
  FROM "bingoscape-next_event_participants" ep
  WINDOW w AS (
    PARTITION BY ep."event_id", ep."user_id"
    ORDER BY CASE ep."role" WHEN 'admin' THEN 0 WHEN 'management' THEN 1 ELSE 2 END,
             ep."created_at" ASC, ep."id" ASC
  )
) r
WHERE r."rn" > 1
ON CONFLICT ("original_id") DO NOTHING;--> statement-breakpoint
UPDATE "bingoscape-next_event_buy_ins" bi
SET "event_participant_id" = r."keeper_id"
FROM (
  SELECT ep."id",
         first_value(ep."id") OVER w AS "keeper_id",
         row_number() OVER w AS "rn"
  FROM "bingoscape-next_event_participants" ep
  WINDOW w AS (
    PARTITION BY ep."event_id", ep."user_id"
    ORDER BY CASE ep."role" WHEN 'admin' THEN 0 WHEN 'management' THEN 1 ELSE 2 END,
             ep."created_at" ASC, ep."id" ASC
  )
) r
WHERE bi."event_participant_id" = r."id" AND r."rn" > 1;--> statement-breakpoint
UPDATE "bingoscape-next_event_donations" d
SET "event_participant_id" = r."keeper_id"
FROM (
  SELECT ep."id",
         first_value(ep."id") OVER w AS "keeper_id",
         row_number() OVER w AS "rn"
  FROM "bingoscape-next_event_participants" ep
  WINDOW w AS (
    PARTITION BY ep."event_id", ep."user_id"
    ORDER BY CASE ep."role" WHEN 'admin' THEN 0 WHEN 'management' THEN 1 ELSE 2 END,
             ep."created_at" ASC, ep."id" ASC
  )
) r
WHERE d."event_participant_id" = r."id" AND r."rn" > 1;--> statement-breakpoint
DELETE FROM "bingoscape-next_event_participants" ep
USING (
  SELECT ep2."id",
         row_number() OVER (
           PARTITION BY ep2."event_id", ep2."user_id"
           ORDER BY CASE ep2."role" WHEN 'admin' THEN 0 WHEN 'management' THEN 1 ELSE 2 END,
                    ep2."created_at" ASC, ep2."id" ASC
         ) AS "rn"
  FROM "bingoscape-next_event_participants" ep2
) r
WHERE ep."id" = r."id" AND r."rn" > 1;--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 4. team_members: first drop repeated rows of one Team, then keep one Team
--    per Player per Event (a Player is on one Team per Event: CONTEXT.md, and
--    the app already moves instead of adding). Keep the leader row, then the
--    oldest. Removed rows go to the quarantine table for manual review.
-- ---------------------------------------------------------------------------
INSERT INTO "bingoscape-next_team_members_quarantine"
  ("reason", "original_id", "team_id", "event_id", "user_id", "is_leader", "original_created_at", "original_updated_at", "kept_team_member_id", "kept_team_id")
SELECT 'duplicate_in_team', r."id", r."team_id", r."event_id", r."user_id", r."is_leader", r."created_at", r."updated_at", r."keeper_id", r."keeper_team_id"
FROM (
  SELECT tm.*,
         first_value(tm."id") OVER w AS "keeper_id",
         first_value(tm."team_id") OVER w AS "keeper_team_id",
         row_number() OVER w AS "rn"
  FROM "bingoscape-next_team_members" tm
  WINDOW w AS (
    PARTITION BY tm."team_id", tm."user_id"
    ORDER BY tm."is_leader" DESC, tm."created_at" ASC, tm."id" ASC
  )
) r
WHERE r."rn" > 1
ON CONFLICT ("original_id") DO NOTHING;--> statement-breakpoint
DELETE FROM "bingoscape-next_team_members" tm
USING (
  SELECT tm2."id",
         row_number() OVER (
           PARTITION BY tm2."team_id", tm2."user_id"
           ORDER BY tm2."is_leader" DESC, tm2."created_at" ASC, tm2."id" ASC
         ) AS "rn"
  FROM "bingoscape-next_team_members" tm2
) r
WHERE tm."id" = r."id" AND r."rn" > 1;--> statement-breakpoint
INSERT INTO "bingoscape-next_team_members_quarantine"
  ("reason", "original_id", "team_id", "event_id", "user_id", "is_leader", "original_created_at", "original_updated_at", "kept_team_member_id", "kept_team_id")
SELECT 'multiple_teams_in_event', r."id", r."team_id", r."team_event_id", r."user_id", r."is_leader", r."created_at", r."updated_at", r."keeper_id", r."keeper_team_id"
FROM (
  SELECT tm.*, t."event_id" AS "team_event_id",
         first_value(tm."id") OVER w AS "keeper_id",
         first_value(tm."team_id") OVER w AS "keeper_team_id",
         row_number() OVER w AS "rn"
  FROM "bingoscape-next_team_members" tm
  INNER JOIN "bingoscape-next_teams" t ON t."id" = tm."team_id"
  WINDOW w AS (
    PARTITION BY t."event_id", tm."user_id"
    ORDER BY tm."is_leader" DESC, tm."created_at" ASC, tm."id" ASC
  )
) r
WHERE r."rn" > 1
ON CONFLICT ("original_id") DO NOTHING;--> statement-breakpoint
DELETE FROM "bingoscape-next_team_members" tm
USING (
  SELECT tm2."id",
         row_number() OVER (
           PARTITION BY t2."event_id", tm2."user_id"
           ORDER BY tm2."is_leader" DESC, tm2."created_at" ASC, tm2."id" ASC
         ) AS "rn"
  FROM "bingoscape-next_team_members" tm2
  INNER JOIN "bingoscape-next_teams" t2 ON t2."id" = tm2."team_id"
) r
WHERE tm."id" = r."id" AND r."rn" > 1;--> statement-breakpoint

