-- 5. Constraints and indexes (safe now that the data is clean)
-- ---------------------------------------------------------------------------
-- Target of the composite foreign key below (a unique constraint, because
-- drizzle-kit push orders foreign keys before indexes). duplicate_table covers
-- the index that the constraint creates under the same name.
DO $$ BEGIN
 ALTER TABLE "bingoscape-next_teams" ADD CONSTRAINT "teams_id_event_id_unique" UNIQUE("id","event_id");
EXCEPTION
 WHEN duplicate_object OR duplicate_table THEN null;
END $$;
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "bingoscape-next_team_members" ADD CONSTRAINT "team_members_team_event_fk" FOREIGN KEY ("team_id","event_id") REFERENCES "public"."bingoscape-next_teams"("id","event_id") ON DELETE cascade ON UPDATE no action;
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
--> statement-breakpoint
