CREATE UNIQUE INDEX IF NOT EXISTS "team_members_team_user_unique" ON "bingoscape-next_team_members" USING btree ("team_id","user_id");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "team_members_event_user_unique" ON "bingoscape-next_team_members" USING btree ("event_id","user_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "team_members_user_idx" ON "bingoscape-next_team_members" USING btree ("user_id");--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 6. Creator rows: every Event whose creator has no participant row gets an
--    admin row, logged in the ledger as 'backfill'.
-- ---------------------------------------------------------------------------
WITH inserted AS (
  INSERT INTO "bingoscape-next_event_participants" ("event_id", "user_id", "role")
  SELECT e."id", e."creator_id", 'admin'
  FROM "bingoscape-next_events" e
  WHERE e."creator_id" IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM "bingoscape-next_event_participants" ep
      WHERE ep."event_id" = e."id" AND ep."user_id" = e."creator_id"
    )
  ON CONFLICT ("event_id", "user_id") DO NOTHING
  RETURNING "event_id", "user_id"
)
INSERT INTO "bingoscape-next_role_change_log"
  ("scope_type", "scope_id", "subject_user_id", "action", "old_role", "new_role", "source", "reason")
SELECT 'event', i."event_id", i."user_id", 'backfill', NULL, 'admin', 'migration', 'creator admin row added by migration 0038'
FROM inserted i;--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 7. Ledger baseline: one row per membership that has no ledger row yet.
-- ---------------------------------------------------------------------------
INSERT INTO "bingoscape-next_role_change_log"
  ("scope_type", "scope_id", "subject_user_id", "action", "old_role", "new_role", "source", "reason")
SELECT 'event', ep."event_id", ep."user_id", 'baseline', NULL, ep."role"::text, 'migration', 'membership existing at ledger introduction'
FROM "bingoscape-next_event_participants" ep
WHERE NOT EXISTS (
  SELECT 1 FROM "bingoscape-next_role_change_log" l
  WHERE l."scope_type" = 'event' AND l."scope_id" = ep."event_id" AND l."subject_user_id" = ep."user_id"
);--> statement-breakpoint
INSERT INTO "bingoscape-next_role_change_log"
  ("scope_type", "scope_id", "subject_user_id", "action", "old_role", "new_role", "source", "reason")
SELECT 'clan', cm."clan_id", cm."user_id", 'baseline', NULL, cm."role"::text, 'migration', 'membership existing at ledger introduction'
FROM "bingoscape-next_clan_members" cm
WHERE NOT EXISTS (
  SELECT 1 FROM "bingoscape-next_role_change_log" l
  WHERE l."scope_type" = 'clan' AND l."scope_id" = cm."clan_id" AND l."subject_user_id" = cm."user_id"
);--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 8. Unique users.username / users.email. Duplicates cannot be merged
--    automatically, and a failing migration would block the whole deploy, so
--    an index is created only when its column has no duplicates; otherwise the
--    migration logs a NOTICE and skips it. To resolve, see
--    docs/DATABASE-MIGRATION.md ("Resolving duplicate usernames and emails").
--    The app compares usernames lower-cased and emails exactly (NextAuth), so
--    the indexes cover the raw columns; case-only email duplicates are
--    reported as a NOTICE but do not block.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  dup_count integer;
BEGIN
  SELECT count(*) INTO dup_count FROM (
    SELECT "username" FROM "bingoscape-next_user" WHERE "username" IS NOT NULL GROUP BY "username" HAVING count(*) > 1
  ) d;
  IF dup_count > 0 THEN
    RAISE NOTICE 'rbac 0038: skipped unique index users_username_unique: % duplicated username(s). Resolve them, then create the index by hand (docs/DATABASE-MIGRATION.md).', dup_count;
  ELSE
    CREATE UNIQUE INDEX IF NOT EXISTS "users_username_unique" ON "bingoscape-next_user" USING btree ("username");
  END IF;

  SELECT count(*) INTO dup_count FROM (
    SELECT "email" FROM "bingoscape-next_user" WHERE "email" IS NOT NULL GROUP BY "email" HAVING count(*) > 1
  ) d;
  IF dup_count > 0 THEN
    RAISE NOTICE 'rbac 0038: skipped unique index users_email_unique: % duplicated email(s). Resolve them, then create the index by hand (docs/DATABASE-MIGRATION.md).', dup_count;
  ELSE
    CREATE UNIQUE INDEX IF NOT EXISTS "users_email_unique" ON "bingoscape-next_user" USING btree ("email");
  END IF;

  SELECT count(*) INTO dup_count FROM (
    SELECT lower("email") FROM "bingoscape-next_user" WHERE "email" IS NOT NULL GROUP BY lower("email") HAVING count(*) > 1
  ) d;
  IF dup_count > 0 THEN
    RAISE NOTICE 'rbac 0038: % email(s) exist in several letter cases (not blocking, review them).', dup_count;
  END IF;
END $$;
